contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // logic performs calls and then asserts the distinguishing property
    // params:
    // addrCaller - the address used as msg.sender when invoking withdraw (simulated by calling from this contract but providing the caller address via tx.origin in mutant scenario);
    // fundFrom - an external address that funds c before withdraw (must be different from addrCaller to expose tx.origin vs msg.sender difference)
    // amount - amount of wei to send when funding and when using Command if needed

    // To interact using different msg.sender within Solidity tests we cannot change msg.sender, so we use the following approach:
    // - First require that this test contract has enough balance to fund c with `amount`.
    // - Fund c by calling payable fallback/receive: send Ether directly to c via address(c).call{value: amount}.
    // - Then perform withdraw by calling c.withdraw() from this contract (so msg.sender == address(this)).
    // The distinguishing mutant uses tx.origin instead of msg.sender; by arranging Owner to be some externally-owned account different from address(this), the mutant may allow withdraw only when tx.origin == Owner whereas original requires msg.sender == Owner and thus will revert here.

    // Because we cannot change who originally deployed C, we observe Owner with its public getter and then assert that withdraw reverts unless the caller equals Owner.

    // The single public test function below follows the required constraints.
    function test_withdraw_only_owner(address caller, address fundFrom, uint256 amount) public payable {
        // preconditions for the harness/verifier
        require(address(this).balance >= amount, "insufficient test contract balance");

        // observe Owner
        address owner = c.Owner();

        // Make sure the depositor (fundFrom) is not the same as the caller to expose tx.origin vs msg.sender differences
        require(fundFrom != caller);

        // Fund c by sending Ether to it from this contract (simulates a deposit). Use top-level call that changes c's state (balance).
        // Note: sending directly to address(c) will trigger receive() and increase its balance.
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "fund failed");

        // Now invoke withdraw from this contract (so msg.sender == address(this)). This is the deciding call.
        // It will succeed on the original (P) only if address(this) == owner. We capture whether it reverts by using low-level call.
        (bool successWithdraw,) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));

        // The rule: withdraw must succeed iff the caller (msg.sender) equals the recorded Owner.
        // Here, msg.sender for the withdraw call is address(this). So successWithdraw must equal (address(this) == owner).
        assert(successWithdraw == (address(this) == owner));
    }

    // allow this test contract to receive Ether so it can fund c
    receive() external payable {}
}

