contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: send some ether into c, then call withdraw from caller and assert
    // that only Owner can drain the balance (i.e., if caller is not Owner, balance should remain >0).
    function run(address caller, uint256 funded) public payable {
        require(address(this).balance >= funded);

        // fund contract c from this test contract
        (bool sent,) = address(c).call{value: funded}("\x00");
        // above will invoke receive() on c and succeed when funded==0 or when value>0
        require(sent);

        // record c balance before withdraw
        uint256 before = address(c).balance;
        require(before == funded);

        // perform withdraw call as the provided caller via low-level call
        // we forward no value and no data
        bytes memory empty;
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("withdraw()"));
        // ok indicates whether the call reverted; capture it

        // After withdraw, if the caller is Owner then contract balance becomes 0; if not Owner, original contract P would have reverted and ok==false and balance unchanged.
        uint256 after = address(c).balance;

        // The distinguishing rule: if the withdraw call succeeded (ok==true), then msg.sender must be the recorded Owner (i.e., owner==caller).
        // We cannot read msg.sender of c, but c.Owner() is public; for the call we made from this contract, the effective caller is this contract, not the provided 'caller' address.
        // To let different callers be represented, the contract behavior reduces to: only c.Owner() can successfully withdraw. So we assert that if withdraw succeeded then the contract's Owner equals address(this).
        assert(!ok || c.Owner() == address(this));
    }

    // Allow this test contract to receive Ether so it can fund c
    receive() external payable {}
}

