contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive interactions and assert: only Owner may trigger withdraw to move c's balance.
    function run(address caller, uint256 sendValue) public {
        // Ensure this test contract has enough balance to send
        require(address(this).balance >= sendValue);

        // Record balance of c before the withdraw attempt
        uint256 before = address(c).balance;

        // Make caller attempt to call withdraw on c by using low-level call to set msg.sender
        // We cannot change msg.sender in Solidity, so instead we model two cases via require:
        // If caller == address(this), we call directly as this contract; otherwise we simulate
        // an external caller by requiring caller to be msg.sender for the test to proceed.
        require(caller == msg.sender);

        // Call withdraw, possibly sending Ether along
        c.withdraw{value: sendValue}();

        // Record balance after
        uint256 after = address(c).balance;

        // General rule: if the caller is NOT the original Owner then withdraw must NOT reduce c's balance
        // This captures that only Owner can successfully withdraw funds.
        // assert: if caller != c.Owner() then after == before + sendValue (i.e., no reduction from withdraw)
        // Note: sendValue may increase the balance by being attached to the call; withdraw from non-owner must not transfer out.
        assert(!(caller != c.Owner()) || after >= before);
    }

    // allow the contract to receive Ether so it can forward to c
    receive() external payable {}
}

