    function testFuzz_property(address caller, uint256 preFund, uint256 sendWithWithdraw) public {
        // keep addresses reasonable: caller must be nonzero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // bound amounts to a practical range
        preFund = bound(preFund, 1, 1e18);
        sendWithWithdraw = bound(sendWithWithdraw, 0, 1e18);

        // The contract's Owner is msg.sender at deployment (setUp), which is this test contract.
        address owner = c.Owner();
        // Make sure fuzzed caller equals Owner to test the owner-invokes-withdraw scenario
        // vm.prank will change msg.sender for external calls; ensure the fuzzed caller matches owner
        // If caller != owner the property is not about withdraw invoked by Owner; constrain to owner
        vm.assume(caller == owner);

        // Fund the contract with preFund from some funding EOA
        address funder = address(0xBEEF);
        vm.deal(funder, preFund + 1 ether);
        vm.prank(funder);
        (bool okFund,) = address(c).call{value: preFund}("");
        require(okFund, "fund failed");

        // Record balances before withdraw
        uint256 ownerBalBefore = owner.balance;
        uint256 contractBalBefore = address(c).balance;

        // Ensure contract had the expected preFund
        assert(contractBalBefore == preFund);

        // Prepare caller to invoke withdraw and send extra value
        vm.deal(caller, sendWithWithdraw + 1 ether);
        vm.prank(caller);
        // Call withdraw with sendWithWithdraw value
        (bool okWithdraw,) = address(c).call{value: sendWithWithdraw}(abi.encodeWithSignature("withdraw()"));

        // Record balances after
        uint256 ownerBalAfter = owner.balance;
        uint256 contractBalAfter = address(c).balance;

        // The general rule: when Owner calls withdraw, Owner's balance must increase by contract's total withdrawn amount
        // For the reference contract, Owner receives the contract's entire balance and contract balance becomes 0.
        // We assert that Owner's balance after is at least ownerBalBefore (i.e., Owner did not lose funds)
        // and that contract's balance is zero. This is a single assertion combining them by checking
        // owner gained exactly contractBalBefore + sendWithWithdraw (the total sent) and contract balance is zero.
        // Since we must have exactly one assertTrue reading c's public surface, we check contract balance is zero
        // and owner balance increased by contractBalBefore + sendWithWithdraw. To avoid flakiness due to gas costs,
        // we check ownerBalAfter >= ownerBalBefore + contractBalBefore + sendWithWithdraw - 1 ether and contractBalAfter == 0
        // but to keep it exact and deterministic we instead assert that contract balance is zero (the core invariant).

        // Single required assertion: contract balance must be zero after Owner called withdraw.
        // The buggy mutant can leave a non-zero balance when it transfers to msg.sender if owner != msg.sender,
        // but here caller == owner so mutant will still send to caller; however the mutant changes target to msg.sender
