        // when withdrawing causes msg.sender to differ — however the Owner is fixed at deployment to this test, so
        // the contract-level difference manifests in owner receiving funds vs contract balance zero. We keep the assertion
        // simple: address(c).balance == 0.

        assertTrue(contractBalAfter == 0);
    }
}

