import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to deposit and an arbitrary caller who will be the owner (owner is msg.sender at deploy)
    // We need at least one fuzz parameter; we fuzz a deposit amount that owner will send to c.
    function testFuzz_property(uint256 deposit) public {
        // keep deposit in a practical range (but wide)
        deposit = bound(deposit, 1 wei, 1 ether);

        // deploy an adversarial owner contract whose receive() will revert to simulate a failing recipient
        AdversarialOwner adv = new AdversarialOwner();

        // fund the adversarial owner so it can send
        vm.deal(address(adv), deposit);

        // The reference contract's Owner was set at c deployment to this test contract's address (msg.sender of setUp)
        // To test the withdraw behavior for Owner, we need the Owner to be the adversarial contract. So
        // deploy a fresh C where Owner is adv by creating c2 via a call from adv. But test requires c created in setUp with new C().
        // Instead, we will have adv become Owner by creating a wrapper that calls withdraw() on the already-deployed c
        // However Owner is fixed; to exercise the difference we will make adv be the Owner by deploying a new instance
        // of C from adv. So create a new C via adv which will set Owner = adv. Use that instance for the check.

        // have adv deploy its own instance of C where it is Owner
        C cOwnedByAdv = adv.deployC();

        // fund the contract to have a balance to withdraw
        // send deposit from adv to cOwnedByAdv
        vm.prank(address(adv));
        (bool sent,) = address(cOwnedByAdv).call{value: deposit}("");
        require(sent);

        // sanity: contract has balance > 0
        assert(address(cOwnedByAdv).balance == deposit);

        // Now call withdraw as adv (Owner). If C uses transfer (reference), transfer will revert because adv.receive() reverts => entire withdraw reverts and balance stays deposit.
        // Wait: The behavioral difference targeted is that transfer reverts on failure, whereas send returns false and does not revert, leaving balance non-zero but call succeeds.
        // To make the mutant (using send) fail the rule (balance becomes zero) we need a scenario where send returns false (i.e., recipient fallback uses too much gas or reverts) -> mutant leaves balance unchanged while reference would revert (so reference would not change balance either?).
        // Correct reasoning: reference using transfer will revert when recipient reverts, so withdraw will revert and balance stays deposit. Mutant using send will ignore failure and continue, leaving balance unchanged as well. That doesn't distinguish.
        // But the user specified the difference: transfer vs send changes gas forwarding and failure behavior when owner calls withdraw. A better rule: withdraw either succeeds and empties contract, or reverts; however with send variant it may succeed (not revert) while funds are NOT forwarded (send returns false) leaving balance non-zero. So we need recipient to revert on receive to cause transfer to revert (withdraw reverts) but send to return false and NOT revert — but send does not revert on recipient revert; it returns false and execution continues, so withdraw would continue but not transfer funds, leaving balance non-zero but call returns success. That means reference call would revert (so caller sees revert) while mutant returns success — difference in revert boolean observed. We'll assert that when Owner's receive reverts, withdraw MUST revert (reference) — i.e., calling withdraw from Owner must revert if Owner's fallback reverts. The mutant will not revert for some inputs because it uses send and ignores failure.

        // So perform the withdraw call from adv and observe whether it reverted.
        bool ok;
        try cOwnedByAdv.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL ASSERTION: For all inputs where the Owner's fallback reverts, the reference contract's withdraw call must revert (ok == false).
        // We observe cOwnedByAdv using only its public surface: whether the call reverted via try/catch.
        // This will pass on the reference (transfer triggers revert) and fail on the mutant (send swallows failure and ok == true for some inputs).
        assertTrue(ok == false);
    }
}

// Adversarial owner whose receive reverts to simulate a failing recipient
contract AdversarialOwner {
    // deploy a new C to become its Owner
    function deployC() external returns (C) {
        return new C();
    }
    receive() external payable {
        revert("no funds");
    }
}

