        vm.prank(attacker);
        // deposit into c
        (bool s, ) = address(c).call{value: deposit}("");
        require(s); // setup must succeed

        // confirm c has the deposited balance before withdraw
        assert(address(c).balance == deposit);

        // Now have the original Owner (deployer of c) be the caller, but set Owner to the reverting helper by direct call
        // Note: Owner in C was set at construction to the test contract (msg.sender at new C()) which is this test contract address.
        // We cannot change c.Owner because it's public but not settable; instead, we simulate the Owner calling withdraw by impersonating the actual Owner.
        // The actual Owner is address(this) (the test contract) because setUp used new C() from this contract.
        // So to trigger transfer to the receiving address, we must change Owner in contract — but Owner is stateful and immutable only by code; instead,
        // we transfer out by having c.send to the Owner address; to observe the behavioral difference we need Owner to be an address with reverting receive.
        // To accomplish this, we deploy a fresh C where Owner is revOwner by constructing from that helper via a small factory.

        // Deploy a new C instance whose Owner will be revOwner by constructing from the reverting contract (msg.sender will be this test contract still),
        // but we cannot make revOwner the msg.sender in C constructor. Instead, we exploit that Owner is set to msg.sender at new C(); so to make Owner==revOwner,
        // we use a factory contract that deploys C with revOwner as msg.sender via a create2 minimal proxy: deploy a Factory that uses delegatecall? Simpler: have the RevertingOwner deploy the C so its address becomes Owner.
        // We'll call a helper on revOwner that deploys a new C from revOwner's context.

        C c2 = revOwner.deployC();

        // fund c2
        vm.deal(attacker, deposit);
        vm.prank(attacker);
        (bool s2, ) = address(c2).call{value: deposit}("");
        require(s2);
        assert(address(c2).balance == deposit);

        // Now impersonate the Owner (which is revOwner) calling withdraw on c2.
        // Since Owner==revOwner and revOwner's receive() reverts, transfer in reference would revert but transfer would propagate revert
        // In the reference contract (using transfer) the withdraw call should revert when sending to revOwner; but the mutant using send would swallow failure => differing behavior.
        // We observe the success/failure of withdraw via try/catch and assert that for the reference contract the withdraw call reverts (ok==false) for this input.

        bool ok;
        try c2.withdraw{value: 0}() {
            ok = true;
