// Helper that reverts on receive and can deploy a new C so that the deployed C has Owner==address(this)
contract RevertingOwner {
    // deploy a new C so that Owner is this contract
    function deployC() external returns (C) {
        C instance = new C();
        return instance;
    }

    receive() external payable {
        revert("revert on receive");
    }
}

