import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to fund the contract and a flag controlling adversarial helper behavior
    function testFuzz_property(uint256 fundAmount, bool helperReverts) public {
        // keep fundAmount in a reasonable wide domain but nonzero (we need some funds to transfer)
        fundAmount = bound(fundAmount, 1, 1 ether);

        // Deploy a helper that will act as Owner and optionally revert on receiving funds
        AttackerOwner ownerHelper = new AttackerOwner(helperReverts);

        // make the helper the owner of c by directly setting Owner via deploying c from that address is impossible here,
        // but C sets Owner = msg.sender at construction; to make Owner be our helper we must deploy c from helper.
        // Since setUp already deployed c from this test, we recreate scenario by deploying a fresh C from the helper.
        // Deploy a new instance of C from the helper by using vm.prank
        vm.prank(address(ownerHelper));
        C cFromHelper = new C();

        // Fund the contract to be withdrawn
        vm.deal(address(this), fundAmount);
        // send funds into cFromHelper
        payable(address(cFromHelper)).transfer(fundAmount);
        assert(address(cFromHelper).balance == fundAmount);

        // Now have the Owner (the helper) call withdraw. If helperReverts is true, its fallback/receive will revert when receiving funds.
        // For the reference contract, transfer will revert and the whole call will revert, leaving balance unchanged (still fundAmount).
        // For the mutant using send, send returns false and does not revert, leaving contract balance > 0 when send fails.

        bool ok;
        vm.prank(address(ownerHelper));
        try cFromHelper.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: For the reference contract, when the Owner calls withdraw the contract balance becomes zero (call either succeeds and drains, or reverts and keeps balance unchanged but the call does not silently succeed while leaving funds).
        // We assert that either the call reverted (ok == false) and balance unchanged (address(cFromHelper).balance == fundAmount),
        // or the call returned (ok == true) and balance is zero. This property holds for the reference but is violated by the mutant which can return ok==true while leaving a nonzero balance.
        assertTrue(
            // either the call reverted and funds remain
            (!ok && address(cFromHelper).balance == fundAmount)
            // or the call returned and funds drained
            || (ok && address(cFromHelper).balance == 0)
        );
    }
}

// adversarial helper: acts as Owner and optionally reverts when receiving Ether
contract AttackerOwner {
    bool public doRevert;
    constructor(bool _doRevert) payable {
        doRevert = _doRevert;
    }
    receive() external payable {
        if (doRevert) revert("revert on receive");
    }
    fallback() external payable {
        if (doRevert) revert("revert on fallback");
    }
}

