        deposit = bound(deposit, 0, 1 ether);

        // deploy a helper to act as Owner with configurable fallback behavior
        OwnerHelper ownerHelper = new OwnerHelper(ownerReverts);

        // fund the helper so it can be Owner and receive funds
        vm.deal(address(ownerHelper), 2 ether);

        // ensure c has some balance by sending deposit from a funder EOA
        address funder = address(0xBEEF);
        vm.deal(funder, 2 ether);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: deposit}(""");
        require(sent || deposit == 0, "funding failed unexpectedly");

        // make ownerHelper the Owner by calling nothing — Owner is set at deployment of c (msg.sender there)
        // we cannot change Owner after deployment. So we must deploy c with ownerHelper as msg.sender.
        // To satisfy the restriction that c is deployed in setUp() using new C(), we instead simulate ownership
        // by using the fact that c.Owner is public; read it and ensure our helper matches it via prank when calling withdraw.
        address owner = c.Owner();

        // If the owner is an EOA (most likely), we still can prank as that owner. However to simulate a failing receive
        // we need the Owner to be a contract. If the actual Owner (deployer) is this test contract, we can make it revert
        // by using a helper only when Owner equals the helper address; otherwise, we instruct the helper to be used as the caller
        // via vm.prank(owner) — but since the fuzzer cannot change c's Owner, we will call withdraw as the real Owner.
        // So we need to ensure the real Owner (deployer in setUp) is either this test contract or the helper. In our setup,
        // setUp deployed c with this test contract as msg.sender, so c.Owner() == address(this).
        // We'll check that and proceed only if that's true; otherwise assume false (to keep domain wide but valid for the property).
        vm.assume(owner == address(this));

        // Now, make the Owner a contract that may revert on receive by using a delegate call pattern:
        // We cannot change c.Owner, but we can have this test contract forward receive behavior by making the test's receive revert
        // based on ownerReverts flag. Implement that by setting a storage flag in this contract via OwnerHelper and using it in
        // this contract's receive(). To keep things minimal and within allowed operations, we instead deploy OwnerHelper and
        // if ownerReverts is true we make withdraw's transfer to this test contract fail by making our fallback revert.
        // However changing this contract's fallback behavior dynamically isn't possible. So instead we simulate by having the Owner
        // be ownerHelper: to satisfy that, we must have deployed c with ownerHelper as msg.sender. But c was deployed in setUp()
        // as this contract. To conform to the requirement that c is deployed with new C() in setUp(), we restrict to the
        // admissible domain where Owner == address(this) (assumed above) and then make this contract's receive behave according
        // to ownerReverts by delegating to ownerHelper through a pre-funded address and using low-level call from withdraw.
        // The only practical way within the constraints is to have this contract's fallback revert when ownerReverts is true.
        // We'll implement receive() below to conditionally revert based on a storage flag set here.

        // set the flag used by this contract's receive()
        _ownerShouldRevert = ownerReverts;

        // call withdraw as Owner (this contract)
        // ensure this contract has enough gas and no pranks necessary
        // capture whether call succeeded or not using try/catch
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

