        deposit = bound(deposit, 0, 1 ether);

        // deploy an adversarial Owner contract that will be set as Owner by construction (msg.sender in setUp was this test, not the Owner contract)
        // To make the deployed C's Owner equal to a contract we control, we need to deploy a new C where Owner is that contract.
        // But setUp already deployed c with Owner = address(this). We'll instead deploy a fresh C where deployer is the Owner helper.
        OwnerHelper owner = new OwnerHelper(ownerReverts);
        // deploy a fresh C with Owner = owner (OwnerHelper deployed will be msg.sender during its constructor)
        C c2 = deployCFrom(owner);

        // fund c2 with deposit
        vm.deal(address(this), deposit);
        if (deposit > 0) {
            // send deposit into c2 via a payable call from this contract
            (bool s,) = address(c2).call{value: deposit}("");
            require(s);
        }

        // now have the OwnerHelper call withdraw
        // OwnerHelper will call c2.withdraw() from its own address
        bool ok = owner.callWithdraw(address(c2));

        // The reference contract guarantees: either withdraw reverts (ok==false) or it succeeds and leaves contract balance == 0
        // The mutant using send can succeed (ok==true) while leaving a nonzero balance when Owner's fallback reverts.
        // We therefore assert the universal property: if the call returned success then address(c2).balance == 0
        // This is the single assertion reading c2's public state
        if (ok) {
            assertTrue(address(c2).balance == 0);
        } else {
            // If call reverted, nothing to assert about balance beyond allowing revert case; still must assert something true
            // The universal property allows revert, so assertTrue(true) is not allowed. Instead assert that ok is false here is not reading c2.
            // To keep a single assertTrue reading c2, observe that when call reverted, contract balance remains unchanged or revert happened; we assert nothing about balance in this branch.
            // But rules require exactly one assertTrue. To satisfy that and have it read c2, we structure as a single assertTrue below combining both cases.
        }

        // Single assertion combining both possibilities: either the call reverted (ok==false) OR balance is zero after success.
        assertTrue((!ok) || (address(c2).balance == 0));
    }

    // helper to deploy C with msg.sender = helper contract
    function deployCFrom(OwnerHelper owner) internal returns (C) {
        // owner will deploy C in its constructor via a call
        return owner.deployC();
