    // Parameters:
    //   adr - target address to call
    //   data - calldata to forward
    //   value - amount of wei to forward with the call
    // Precondition: this contract must hold enough balance to forward `value` to c.Command (we transfer to c via payable fallback by calling multiplicate with 0 value first if needed)
    function check(address adr, bytes memory data, uint256 value) public {
        require(address(this).balance >= value);

        // Ensure c has at least `value` so that the call from c.Command can forward value (not strictly necessary but keeps balances sensible)
        // If c has insufficient balance, sending value to it via its receive by calling multiplicate with 0 is a way to fund it,
        // but multiplicate may forward out funds; we skip funding and rely on caller-provided precondition.

        // Call Command forwarding `value` wei. In P the low-level call is allowed to fail silently; in M it will revert on failure.
        // We capture whether the call reverted by making an external call and observing success via low-level call here.
        // To observe post-call effects we record balances before and after.

        uint256 balBefore = address(adr).balance;
        uint256 cBalBefore = address(c).balance;

        // Make the call to c.Command and capture whether it reverted.
        (bool ok, ) = address(c).call{value: value}(abi.encodeWithSignature("Command(address,bytes)", adr, data));

        uint256 balAfter = address(adr).balance;
        uint256 cBalAfter = address(c).balance;

        // Assert: if the external target gained any Ether (balAfter > balBefore) then the Command call must have returned success (ok == true).
        // Equivalently: ok || (balAfter == balBefore)
        assert(ok || (balAfter == balBefore));
    }

    // allow contract to receive Ether for testing
    receive() external payable {}
}

