pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to send and an arbitrary nonce-influencing value
    // We fuzz a uint256 valueAmt which will be the Ether forwarded in Command.
    function testFuzz_property(uint256 valueAmt) public {
        // keep valueAmt in reasonable range so vm.deal works and we don't overflow
        uint256 amt = bound(valueAmt, 0, 1 ether);

        // Deploy an adversarial helper that expects a state-changing payable call.
        // This helper will revert if invoked via staticcall (since it tries to modify state),
        // or will accept value when called normally.
        HelperReceiver helper = new HelperReceiver();

        // Fund the caller (owner). The contract c was deployed by this test account (address(this)),
        // and its Owner is address(this). We will call Command from address(this) so require(msg.sender==Owner) holds.
        vm.deal(address(this), amt);

        // Call Command on c, forwarding amt wei to the helper via c.Command.
        // We wrap call in try/catch to observe whether the low-level invocation succeeded.
        bool ok;
        try c.Command{value: amt}(address(helper), abi.encodeWithSelector(HelperReceiver.doSomething.selector)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL ASSERTION (single assertTrue): For the correct contract, invoking Command
        // with arbitrary amt should succeed when calling a helper that performs state changes and is payable.
        // The mutant using staticcall (and not forwarding value) will cause the call to fail for some amt (e.g., >0),
        // so this property will catch the mutant.
        assertTrue(ok);
    }
}

// Adversarial helper: requires being called non-statically and payable; it mutates its state.
contract HelperReceiver {
    uint256 public x;

    // function that modifies state; will revert if called via staticcall
    function doSomething() external payable {
        // require it is payable and changes state
        require(msg.value >= 0);
        x += 1;
    }
}
